contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 betLimitAmount, uint256 difficultyAmount, uint256 wagerAmount) public payable {
        require(address(this).balance >= betLimitAmount + wagerAmount + difficultyAmount);

        // Owner opens the contract to the public.
        c.OpenToThePublic();

        // Owner sets the bet limit and difficulty.
        c.AdjustBetAmounts(betLimitAmount);
        c.AdjustDifficulty(difficultyAmount);

        // The test contract places a wager at the current bet limit.
        bool wagerReverted;
        try c.wager{value: betLimitAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        bool hadWagerBefore = c.hasPlayerWagered(address(this));

        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        bool hadWagerAfter = c.hasPlayerWagered(address(this));

        // play() must revert if the wager did not succeed, otherwise it must not revert
        // (the wager was placed in the same block, so timestamp < block.number is false).
        // When it does not revert, the player's wager is cleared.
        assert((wagerReverted && playReverted && !hadWagerAfter) ||
               (!wagerReverted && !playReverted && hadWagerBefore && !hadWagerAfter));
    }

    receive() external payable {}
}

